<?php global $wpdb; $rule=sanitize_text_field($_GET['rule']??'ghunnah'); $rows=$wpdb->get_results($wpdb->prepare("SELECT ayah_id,start_pos,end_pos,tooltip FROM {$wpdb->prefix}quran_tajweed WHERE rule_type=%s LIMIT 50",$rule),ARRAY_A); ?><!doctype html><html><body><h1>Tajweed Rule: <?php echo esc_html($rule); ?></h1><?php foreach($rows as $r): ?><p><?php echo esc_html('Ayah '.$r['ayah_id'].' '.$r['tooltip']); ?></p><?php endforeach; ?></body></html>
